import numpy as np, base64, json

def b64(x):
    return base64.b64encode(np.asarray(x,dtype=np.int16).tobytes()).decode()

# oneshots of various lengths, all 440Hz content
def mkoneshot(n, f=440.0, amp=0.8):
    t=np.arange(n)/44100.0
    return (np.sin(2*np.pi*f*t)*amp*32767).astype(np.int16)

