     {"name":"module_save","arguments":{"path":f"/workspace/len{n}.xm","format":"xm"}},
     {"name":"module_render","arguments":{"path":f"/workspace/len{n}.wav","rate":22050,"bits":16,"amp":1,"loops":1,"start":0,"stop":64}}
    ]
open('batch_len.json','w').write(json.dumps(batch))
print("ok")
